SELECT 'moj-all-verified-judgments-review-002-chunk-153' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"db693e32-7b0a-54d2-9fb7-554b3ea6860d","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -البينة الكتابية -اعتراف املقر بالتوقيع دون مضمون اإلقرار -احلكم باإلقرار واليمن -إلزام املدعى عليه بدفع مبلغ القرض.","document_number":"3435223","case_number":"32399423","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة القطيف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/11","year":"1434","subject":"قرض -البينة الكتابية -اعتراف املقر بالتوقيع دون مضمون اإلقرار -احلكم باإلقرار واليمن -إلزام املدعى عليه بدفع مبلغ القرض.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/2/11 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3435223 :‬‬\n                   ‫َر ْق ُم الدعوى‪32399423 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 3465189‬تاريخه‪1434/3/17 :‬هـ‬\n\n\n\n‫قــرض ‪ -‬البينــة الكتابيــة ‪ -‬اعتــراف املقــر بالتوقيع دون مضمون اإلقرار‬\n  ‫‪ -‬احلكــم باإلقــرار واليمــن ‪ -‬إلــزام املدعــى عليــه بدفــع مبلغ القرض‪.‬‬\n\n\n\n\n‫مــا قــرره يف مطالــب أولــي النهــى (‪)684/6‬طبعــة املكتــب اإلســامي ‪:‬‬\n‫(ومــن أقــر أنــه وهــب زيــد ًا كــذا وأقبضــه إيــاه أو أقــر أنــه رهــن زيــد ًا‬\n‫كــذا و أقبضــه أو أقــر بقبــض ثمــن أو غيــره كأجــرة ومبيــع ثــم قــال مــا‬\n‫أقبضنــي الهبــة وال الرهــن وال قبضــت الثمــن ونحــوه وهــو غيــر جاحــد‬\n‫إلقــراره باإلقبــاض أو القبــض وال بينــة وســأل إحــاف خصمــه لزمــه‬\n                                       ‫جلريــان العــادة باإلقــرار بذلــك قبلــه )‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة علــى املدعــى عليــه بأنــه اقتــرض منهــا مبالــغ ماليــة علــى‬\n‫ثــاث دفعــات وطلبــت إلزامــه بدفعهــا ‪ ،‬أنكــر املدعــى عليــه مــا جــاء يف‬\n‫دعــوى املدعيــة ‪ ،‬بطلــب البينــة مــن املدعيــة أبــرزت إقــرار ًا خطيـ ًا منســوب ًا‬\n‫للمدعــى عليــه ‪ ،‬جــرى االطــاع علــى هــذا اإلقــرار ورصــده ‪ ،‬وبعرضــه‬\n‫علــى املدعــى عليــه أقــر بــأن التوقيــع توقيعــه و أنكــر اســتالم مبلغــن‬\n‫وذكــر بــأن املبلــغ الثالــث جمعيــة اســتلمها مــن أختــه وهــي للمدعيــة‬\n\n\n                                                                                          ‫‪28‬‬\n\f     ‫وقــد وهبتهــا لــه ‪ ،‬أنكــرت املدعيــة هــذه الهبــة وحلفــت اليمــن بعــد أن‬\n     ‫طلــب املدعــى عليــه ذلــك ‪ ،‬لــم يطلــب املدعــى عليــه ميــن املدعيــة علــى‬\n     ‫نفيــه الســتالم املبلغــن اآلخريــن ‪ ،‬صــدر احلكــم بإلــزام املدعــى عليــه‬\n     ‫بدفــع املبلــغ املدعــى بــه للمدعيــة ‪ ،‬اعتــرض املدعــى عليــه علــى احلكــم ‪،‬‬\n                                     ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وآلــه وصحبــه أمــا‬\n     ‫بعــد فلــدي أنــا ‪ ...‬القاضــي يف املكتــب القضائــي العاشــر باحملكمــة‬\n     ‫العامــة مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n                                                                                     ‫ّ‬\n     ‫العامــة مبحافظــة القطيــف برقــم ‪ 32399423‬وتاريــخ‬       ‫َ‬      ‫رئيــس احملكمــة‬\n     ‫‪1432/09/08‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321164647‬وتاريــخ‬\n     ‫‪ 1432/09/08‬ه ـ فقــد حضــرت ‪...‬حتمــل الســجل املدنــي ذا الرقــم‬\n     ‫‪...‬املعــرف بهــا مــن وكيلها‪...‬يحمــل الســجل املدنــي رقــم ‪...‬مبوجــب‬\n     ‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بالدمــام رقــم ‪41758‬‬\n     ‫يف ‪1432/08/17‬ه ـ اجللــد ‪ 9566‬وادعــى الوكيــل علــى احلاضــر معــه‬\n     ‫باملجلــس ‪ ...‬يحمــل الســجل املدنــي ذا الرقــم ‪...‬قائــا ‪ :‬إن ملوكلتــي‬\n     ‫بذمــة املدعــى عليــه مبالــغ ماليــة قدرهــا جملــة وهــو مائــة واثنــان وأربعــون‬\n     ‫ألــف ريــال (‪142000‬ريــال) وتفصيــل ذلــك علــى النحــو اآلتــي ‪ /1‬مائــة‬\n     ‫ألــف ريــال (‪ 100000‬ريــال) أقرضتــه إيــاه ‪ /2‬ســتة عشــر ألــف ريــال‬\n     ‫(‪16000‬ريــال) أقرضتــه إيــاه أيضــا يف عقــد مســتقل عــن األول ‪ /3‬ســتة‬\n     ‫وعشــرون ألــف ريــال (‪ 26000‬ريــال) أقرضتــه إيــاه يف عقــد مســتقل عــن‬\n     ‫العقديــن األولــن وقــد ســلمتها لــه نقــدا وقــد طلبــت منــه إعادتهــا فلــم‬\n\n‫‪29‬‬\n\f‫يفعــل أطلــب إلزامــه بإعادتهــا ملوكلــي هكــذا قــرر وبعــرض الدعــوى‬\n‫عليــه أجــاب عنهــا قائــا مــا ذكــره وكيــل املدعيــة غيــر صحيــح فليــس‬\n‫لهــا يف ذمتــي أي مبلــغ ملــا ذكــر وكيلهــا هكــذا قــرر وبالســؤال عــن‬\n‫البينــة أبــرزت املدعيــة اإلقــرار املــؤرخ يف ‪1432/6/16‬ه ـ وممــا تضمنــه‪:‬‬\n‫( أقــر وأعتــرف أنــا‪ ) ......‬وفيــه ( أن يف ذمتــي للســيدة ‪ ...‬برقــم بطاقــة‪.../‬‬\n‫كاآلتــي‪ :‬مبلــغ مقــداره مائــة ألــف ريــال دينــا ولهــا أيضــا يف ذمتــي‬\n‫‪15000‬ألــف ريــال مهــرا و ‪ 16000‬ريــال قرضــا يحــق لهــا قبــل إبــرام‬\n‫عقــد الطــاق األول كمــا لهــا يف ذمتــي مبلــغ ســتة وعشــرون ألــف ريــال‬\n‫كجمعيــة تســتلمها يف شــهر شــوال مــن هــذا العــام ‪1432‬ه ـ ) وبعرضــه‬\n‫علــى املدعــى عليــه قــال إن التوقيــع توقيعي واملائة ألــف ريال لم أقترضها‬\n‫واملهــر اخلمســة عشــر ألــف ريــال ســلمته لهــا يف ‪1432/8/30‬ه ـ والســتة‬\n‫عشــر ألــف ريــال لــم أقترضهــا والســتة وعشــرون ألــف يف ذمتــي وهــي‬\n‫جمعيــة اســتلمتها مــن أختــي ‪...‬وهــي حــق للمدعيــة وقــد وهبتنــي إياهــا‬\n‫هكــذا قــرر وبســؤال املدعيــة هــل اســتلمت املهــر اخلمســة عشــر ألــف‬\n‫ريــال فقالــت نعــم هكــذا قــررت وبســؤالها عــن الهبــة التي ذكــر املدعي‬\n‫قالــت إن ذلــك غيــر صحيــح وبســؤال املدعــى عليــه عــن بينتــه علــى الهبــة‬\n‫قــال ال بينــة لــي فأفهمتــه بــأن لــه ميينهــا فقــال أطلــب ميينهــا وبعرضــه علــى‬\n‫املدعيــة اســتعدت ببــذل اليمــن وحلفــت بعــد تخويفهــا مــن عاقبــة اليمــن‬\n‫الكاذبــة واإلذن لهــا قائلــة ‪ :‬واهلل العظيــم إننــي لــم أهــب املدعــى عليــه‬\n‫هــذا احلاضــر الســتة وعشــرين ألــف ريــال التــي ذكــر هكــذا حلفــت‬\n‫والنتهــاء وقــت اجللســة فقــد رفعــت ثــم افتتحــت وفيهــا حضــر ‪...‬يحمــل‬\n‫الســجل املدنــي ذا الرقــم ‪...‬بصفتــه وكيــا عــن ‪...‬مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة عــدل محافظــة القطيــف ذات الرقــم ‪33450348‬‬\n\n\n                                                                                           ‫‪30‬‬\n\f     ‫يف ‪1433/12/19‬ه ـ كمــا حضــر املدعــى عليــه وبســؤال املدعــى عليــه‬\n     ‫عــن معنــى لــم أقترضهــا الــواردة يف جوابــه فقــال ‪ :‬لــم أســتلمها هكــذا‬\n     ‫قــرر فســألته ألــك بينــة فقــال ‪ :‬ال ‪ .‬فأفهمتــه بــأن لــه ميــن املدعيــة علــى‬\n     ‫وفــق مــا ادعتــه فقــال ال أريــد ميينهــا هكــذا قــرر وقــررت املدعيــة قائلــة‪:‬‬\n     ‫ال مانــع لــدي مــن بــذل اليمــن هكــذا قــررت فبنــاء علــى مــا تقــدم مــن‬\n     ‫الدعــوى واجلــواب وإلقــرار املدعــى عليــه بإمضائــه املشــار إليــه ولدفعــه‬\n     ‫بعــدم االســتالم ملائــة ألــف ريــال ولســتة عشــر ألــف ريــال املشــار لهمــا‬\n     ‫يف الدعــوى وال بينــة لــه علــى ذلــك ولــم يرغــب يف ميــن املدعــى عليهــا‬\n     ‫وألنــه دفــع بــأن املدعيــة وهبــت الســتة وعشــرين ألــف ريــال فأنكــرت‬\n     ‫وال بينــة لــه وطلــب ميينهــا فحلفــت علــى النفــي وملــا قــرره يف مطالــب‬\n     ‫أولــي النهــى ‪ 684/6‬طبعــة املكتــب اإلســامي ‪ ( :‬ومــن أقــر أنــه وهــب‬\n     ‫زيــدا كــذا وأقبضــه إيــاه أو أقــر أنــه رهــن زيــدا كــذا وأقبضــه أو أقــر‬\n     ‫بقبــض ثمــن أو غيــره كأجــرة ومبيــع ثــم قــال مــا أقبضــت الهبــة وال‬\n     ‫الرهــن وال قبضــت الثمــن ونحــوه وهــو غيــر جاحــد إلقــراره باإلقبــاض أو‬\n     ‫القبــض وال بينــة وســأل إحــاف خصمــه لزمــه جلريــان العــادة باإلقــرار‬\n     ‫بذلــك قبلــه ) لذلــك كلــه فقــد ألزمــت املدعــى عليــه أن يســلم للمدعيــة‬\n     ‫مائــة واثنــن وأربعــن ألــف ريــال ( ‪ 142000‬ريــال ) املدعــى بهــا وبذلــك‬\n     ‫حكمــت وبعــرض احلكــم علــى احملكــوم عليــه قــرر عــدم القناعــة‬\n     ‫والرغبــة يف رفــع احلكــم حملكمــة االســتئناف بــدون الئحــة لــذا أجبــت‬\n     ‫طلبــه وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                    ‫‪1434/02/11‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وآلــه وصحبــه‬\n     ‫العامــة مبحافظــة القطيــف‬‫ّ‬      ‫أمــا بعــد فلــدي أنــا ‪...‬القاضــي يف احملكمــة‬\n\n\n‫‪31‬‬\n\f‫العامــة‬\n    ‫َ‬     ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫مبحافظــة القطيــف برقــم ‪ 32399423‬وتاريــخ ‪1432/09/08‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 321164647‬وتاريــخ ‪ 1432/09/08‬ه ـ فقــد عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية وبهــا القــرار ذو‬\n‫الرقــم ‪ 3465189‬يف ‪1434/3/17‬ه ـ املتضمــن مــا نصــه بعــد املقدمــة ‪:‬‬\n‫( وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة وكذلــك االســتدعاء‬\n‫املقيــد لــدى احملكمــة برقــم ‪ 34623807‬وتاريــخ ‪1434/3/11‬ه ـ املقدم‬\n‫مــن وكيــل املدعــى عليــه قررنــا املصادقــة علــى احلكــم وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                               ‫‪ 1434/03/25‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪ 34512697‬وتاريــخ ‪1434/ 2/30‬ه ـ الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة مبحافظة القطيف برقــم ‪321164647‬‬\n‫وتاريــخ ‪1434/2/25‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضي‬\n‫باحملكمــة الشــيخ‪ .../‬املســجل برقــم ‪ 3435223‬وتاريــخ ‪1434/2/11‬هـ‬\n‫بشــأن دعوى‪.../‬ضــد‪.../‬يف قضيــة حقوقيــة وقــد تضمــن الصــك حكــم‬\n‫فضيلــة القاضــي مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة‬\n‫ضبطــه وأوراق املعاملــة وكذلــك االســتدعاء املقيــد لــدى احملكمــة‬\n‫برقــم ‪34623807‬وتاريخ‪1434/3/11‬ه ـ املقــدم مــن وكيــل املدعــى‬\n‫عليــه قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                       ‫محمــد وآلــه وصحبــه وســلم حــرر يف‪1434/3/17‬ه ـ ‪.‬‬\n\n\n\n                                                                                       ‫‪32‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":28,"source_page_end":32,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"58eca7ebfb7abc56164c4089f12e30bfcec82b1f6d4e8098cb852365d0ebe153","normalized_text_hash":"dd036aa175bfdcb22187c0ea40c8b7a5ffb6d361c3e49c2bbaa1ac28eeb628f7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p28-3435223"},{"id":"4f17d378-b1f5-543c-ad27-e2a89bbc8e1a","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -مطالبة بقسط مؤجل لتخلف شرط االلتزام بسداد األقساط احلالة يف حينها -وجوب الوفاء بالعقود -إخطار املدعى عليه الغائب باحلكم -احلكم بالشاهد العدل ومين املدعي -حكم على غائب -حكم بتسليم مبلغ مؤجل .","document_number":"3436038","case_number":"33412046","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/12","year":"1434","subject":"قرض -مطالبة بقسط مؤجل لتخلف شرط االلتزام بسداد األقساط احلالة يف حينها -وجوب الوفاء بالعقود -إخطار املدعى عليه الغائب باحلكم -احلكم بالشاهد العدل ومين املدعي -حكم على غائب -حكم بتسليم مبلغ مؤجل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/2/12 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪3436038 :‬‬\n                        ‫َر ْق ُم الدعوى‪33412046 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34256805‬تاريخه‪1434/7/2:‬هـ‬\n\n\n\n     ‫قــرض ‪ -‬مطالبــة بقســط مؤجــل لتخلــف شــرط االلتــزام بســداد‬\n     ‫األقســاط احلالــة يف حينهــا‪ -‬وجــوب الوفــاء بالعقــود‪ -‬إخطــار املدعــى‬\n     ‫عليــه الغائــب باحلكــم‪ -‬احلكــم بالشــاهد العــدل وميــن املدعــي‪ -‬حكــم‬\n                                 ‫علــى غائــب ‪ -‬حكــم بتســليم مبلــغ مؤجــل ‪.‬‬\n\n\n\n\n                        ‫‪ -1‬قوله تعالى «يا أيها الذين آمنوا أوفوا بالعقود»‪.‬‬\n     ‫‪ -2‬قولــه صلــى اهلل عليــه وســلم «املســلمون علــى شــروطهم» رواه‬\n                                                          ‫الترمــذي وأبــو داود‪.‬‬\n     ‫‪ -3‬قولــه صلــى اهلل عليــه وســلم « علــى اليــد مــا أخــذت حتــى تؤديــه»‬\n                                                                   ‫رواه األربعــة ‪.‬‬\n     ‫‪ -4‬قولــه صلــى اهلل عليــة وســلم « البينــة علــى املدعــى واليمــن علــى‬\n                                               ‫املدعــى عليــه « رواه الترمــذي ‪.‬‬\n                       ‫‪ -5‬املادة (‪ )55‬و (‪ )176‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n‫‪33‬‬\n\f‫دعــوى املدعــى ضــد املدعــى عليــه الغائــب عــن مجلــس احلكــم الــذي بلــغ‬\n‫مبوعــد اجللســة لشــخصه ومضمــون الدعــوى أن املدعــي اقــرض املدعــى‬\n‫عليــه مبلغــا قــدرة مائــة وخمســون ألــف ريــال تســلم علــى ثالثــة أقســاط‬\n‫كل قســط خمســون ألــف ريــال ولــم يلتــزم بســداد األقســاط يف حينهــا‬\n‫وطلــب املدعــي إلــزام املدعــى عليــه بســداد املبلــغ الــذي يف ذمــة املدعــى‬\n‫ا ‪ ،‬طلــب ناظــر القضيــة البينــة علــى الدعــوى ‪ ،‬أبــرز املدعــي‬    ‫عليــه كامـ ً‬\n‫إقــرار ًا منســوبا للمدعــى عليــه يتضمــن صحــة الدعــوى ‪ ،‬احضــر املدعــي‬\n‫شــاهد ًا شــهد بصحــة الدعــوى ومت تعديلــه شــرع ًا ‪ ،‬جــرى عــرض اليمــن‬\n‫علــى املدعــى وحلــف علــى صحــة دعــواه ‪ ،‬بنــاء علــى األســباب املرصــودة‬\n‫يف احلكــم ولقولــه تعالــى ((يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود)) صــدر‬\n‫احلكــم بإلــزام املدعــى عليــه باملبلــغ املدعــى بــه ‪ ،‬مت تزويــد املدعــى عليــه‬\n‫بصــورة مــن احلكــم ‪ ،‬قــدم املدعــى عليــه الئحــة اعتراضيــة اطلــع عليهــا‬\n‫حاكــم القضيــة ولــم يظهــر لــه خــاف مــا حكــم بــه ‪ ،‬صــدر قــرار‬\n                             ‫محكمــة االســتئناف باملوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 33412046‬وتاريــخ‬\n‫‪1433/06/18‬ه ـ امل ـ ـ ــقيدة باحملكمــة برقـ ـ ــم ‪ 331151579‬وتاريــخ‬\n‫‪1433/06/18‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪1434/02/12‬ه ـ افتتحــت‬\n                                                                                        ‫‪34‬‬\n\f     ‫اجللســة الســاعة ‪ 09 : 00‬وفيهــا حضــر املدعــي ‪ /‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ولــم يحضــر املدعــى عليــه وال مــن ميثلــه‪،‬‬\n     ‫وقــد وردنــا التبليــغ مــن قســم احملضريــن مفــاده تبليــغ املدعــى عليــه‬\n     ‫لشــخصه ‪ ،‬فبنــاء علــى املــادة ‪ 55‬مــن نظــام املرافعــات الشــرعية فقــد‬\n     ‫قــررت النظــر يف الدعــوى غيابيــا يف حــق املدعــى عليــه ‪ ،‬وادعــى املدعــي‬\n     ‫قائــا ‪ :‬لقــد أقرضــت املدعــى عليــه مبلغــا ماليــا قــدره مائــة وخمســون‬\n     ‫ألــف ريــال يف عــام ‪1432‬ه ـ ‪ ،‬ثــم اتفقنــا علــى أن يتــم ســدادها علــى‬\n     ‫أقســاط كالتالــي ‪ :‬الدفعــة األولــى وقدرهــا خمســون ألــف ريــال يف‬\n     ‫‪1433/7/26‬ه ـ ‪ ،‬والدفعــة الثانيــة وقدرهــا خمســون ألــف ريــال يف‬\n     ‫‪1434/1/26‬ه ـ ‪ ،‬والدفعــة الثالثــة وقدرهــا خمســون ألــف ريــال يف‬\n     ‫‪1434/7/24‬ه ـ ‪ ،‬علــى أنــه يف حــال تأخــره عــن ســداد أي دفعــة يف‬\n     ‫املوعــد احملــدد لهــا فإنــه يكــون ملتــزم بدفــع كامــل املبلــغ وقــدره مائــة‬\n     ‫وخمســون ألــف ريــال دفعــة واحــدة ‪ ،‬وقــد مت حتريــر إقــرار بذلــك مــن‬\n     ‫املدعــى عليــه ومذيــل بتوقيعــه يف ‪1433/1/24‬ه ـ وبشــهادة كال مــن ‪/‬‬\n     ‫و ‪ ، /‬ولــم يســدد املدعــى عليــه مــن ذلــك املبلــغ شــيئا حتــى اليــوم ‪ ،‬أطلــب‬\n     ‫إلــزام املدعــى عليــه بدفــع كامــل املبلــغ وقــدره مائــة وخمســون ألــف ريال‬\n     ‫‪ .‬هــذه دعــواي ‪ .‬ثــم أبــرز املدعــي أصــل اإلقــرار املشــار إليــه ‪ ،‬ومت تزويــد‬\n     ‫أوراق املعاملــة بنســخة منــه ‪ ،‬وبطلــب زيــادة بينــة مــن املدعــي علــى صحــة‬\n     ‫دعــواه أحضــر للشــهادة وأدائهــا ‪ /‬ســعودي اجلنســية مبوجــب الســجل‬\n     ‫املدنــي رقــم وهــو مــن مواليــد ‪1400‬ه ـ ويعمــل يف مجــال احملامــاة ‪،‬‬\n     ‫وليــس بينــه وبــن أطــراف الدعــوى قرابــة ‪ ،‬وهــو صديــق لطــريف الدعــوى‬\n     ‫‪ ،‬وشــهد قائــا ‪ :‬أشــهد بــاهلل العظيــم بــأن املدعــى عليــه أقــر أمامــي ويف‬\n     ‫مكتبــي بــأن يف ذمتــه للمدعــي مبلغــا قــدره مائــة وخمســون ألــف ريــال‬\n\n\n‫‪35‬‬\n\f‫قرضــة حســنة ‪ ،‬وقــد وقــع علــى اإلقــرار املشــار إليــه يف الدعــوى أمامــي‬\n‫وكنــت أحــد الشــهود عليــه ‪ .‬هكــذا شــهد ‪ .‬وعــدل مــن قبــل ‪ /‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ،‬وبعــرض اليمــن علــى املدعــي‬\n‫علــى صحــة دعــواه وعــدم اســتالمه مــن مبلــغ القرضــة محــل الدعــوى‬\n‫شــيئا اســتعد لذلــك ‪ ،‬ثــم حلــف قائــا ‪ :‬واهلل العظيــم الــذي ال إلــه إال‬\n‫هــو أننــي أقرضــت املدعــى عليــه مبلغــا ماليــا قــدره مائــة وخمســون ألــف‬\n‫ريــال يف عــام ‪1432‬ه ـ ‪ ،‬ثــم اتفقنــا يف ‪1433/1/24‬ه ـ علــى أن يتــم‬\n‫ســدادها علــى أقســاط كالتالــي ‪ :‬الدفعــة األولــى وقدرهــا خمســون‬\n‫ألــف ريــال يف ‪1433/7/26‬هــ‪ ،‬والدفعــة الثانيــة وقدرهــا خمســون ألــف‬\n‫ريــال يف ‪1434/1/26‬ه ـ ‪ ،‬والدفعــة الثالثــة وقدرهــا خمســون ألــف ريــال‬\n‫يف ‪1434/7/24‬ه ـ ‪ ،‬علــى أنــه يف حــال تأخــره عــن ســداد أي دفعــة يف‬\n‫املوعــد احملــدد لهــا فإنــه يكــون ملتــزم بدفــع كامــل املبلــغ وقــدره مائــة‬\n‫وخمســون ألــف ريــال دفعــة واحــدة ‪ ،‬ولــم يســددني مــن ذلــك املبلــغ شــيئا‬\n‫حتــى اليــوم ‪ .‬هكــذا حلــف ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى والبينــة‬\n‫املتمثلــة يف ســند اإلقــرار املــؤرخ يف ‪1433/1/24‬ه ـ ‪ ،‬وشــهادة الشــاهد‬\n‫واملعدلــة مــن قبــل ‪ ،‬وبنــاء علــى ميــن املدعــي علــى صحــة دعــواه وعــدم‬\n‫اســتالمه مــن مبلــغ القرضــة محــل الدعــوى شــيئا حتــى اليــوم ‪ ،‬ولقولــه‬\n‫تعالــى (يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود) ‪ ،‬وحلديــث (املســلمون علــى‬\n‫شــروطهم) رواه الترمــذي وأبــو داوود ‪ ،‬وحلديــث (علــى اليــد مــا أخــذت‬\n‫حتــى تؤديــه) رواه األربعــة ‪ ،‬وحلديــث (البينــة علــى املدعــي واليمــن علــى‬\n‫املدعــى عليــه) رواه الترمــذي ‪ ،‬قــال أبــو عيســى ‪ :‬العمــل عنــد أهــل‬\n‫العلــم مــن أصحــاب النبــي صلــى اهلل عليــه وســلم وغيرهــم أن البينــة‬\n‫علــى املدعــي واليمــن علــى املدعــى عليــه ‪ ،‬وبنــاء علــى املــادة ‪ 55‬و ‪176‬‬\n\n\n                                                                                       ‫‪36‬‬\n\f     ‫مــن نظــام املرافعــات الشــرعية ‪ ،‬لذلــك كلــه ‪ ،‬فقــد حكمــت علــى‬\n     ‫املدعــى عليــه بدفــع مبلــغ وقــدره مائــة وخمســون ألــف ريــال للمدعــي‪ .‬وبــه‬\n     ‫حكمــت ‪ .‬وبــه قنــع املدعــي ‪ ،‬وقــررت بعــث نســخة مــن احلكــم للغائــب‬\n     ‫عــن مجلــس القضــاء لتبليغــه باحلكــم ‪ ،‬وإفهامــه بــأن لــه حــق االعتــراض‬\n     ‫علــى احلكــم خــال ثالثــن يومــا مــن تاريــخ اســتالمه نســخة احلكــم ‪،‬‬\n     ‫وإال ســقط حقــه يف االعتــراض ‪ ،‬واكتســب احلكــم القطعيــة ‪ .‬وأقفلــت‬\n     ‫اجللســة الســاعة ‪ . 09 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                 ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/12‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة‬\n     ‫مبحافظــة جــدة ففــي يــوم األربعــاء املوافــق ‪1434/05/29‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 12 : 00‬وفيهــا وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n     ‫بخطــاب رئيســها رقــم ‪ 331151579‬وتاريــخ ‪1434/4/30‬ه ـ ومرفــق‬\n     ‫بــه القــرار رقــم ‪ 34198378‬وتاريــخ ‪1434/4/27‬ه ـ املتضمــن أنــه‬\n     ‫(تقــرر باألكثريــة إعادتهــا لفضيلــة حاكمهــا ملالحظــة مــا يلــي ‪-1 :‬‬\n     ‫عــدم اســتكمال تعديــل الشــاهد ‪ -2‬ذكــر املدعــى عليــه يف الئحتــه‬\n     ‫االعتراضيــة مــا يوجــب حتديــد موعــد لــه ومناقشــة مــا ذكــر فيهــا‬\n     ‫حــال حضــور الطرفــن فعلــى فضيلتــه اســتكمال مــا يلــزم وأخــذ‬\n     ‫توقيــع املعتــرض واســمه علــى الالئحــة حســب التعليمــات) وعليــه أجيــب‬\n     ‫أصحــاب الفضيلــة فيمــا يخــص املالحظــة األولــى فــإن تعديــل الشــهود لــم‬\n     ‫يــرد يف كتــاب اهلل وال ســنة رســوله ولــم يكــن ســلف األمــة يعملــون بــه ‪،‬‬\n     ‫بــل ورد يف كتــاب اهلل احلــث علــى استشــهاد ذوو العــدل فقــط ‪ ،‬فمتــى‬\n     ‫لــم يقــع يف قلــب القاضــي ريبــة يف الشــاهد وشــهادته فــا يلــزم تعديلــه ‪،‬‬\n     ‫واألصــل أمانــة املســلم وعدالتــه ‪ ،‬واملقصــود مــن تعديــل الشــهادة شــهادة‬\n\n\n‫‪37‬‬\n\f‫مــن يعرفــه القاضــي ويعلــم حالــه بــأن الشــاهد ‪-‬الــذي ال يعلــم القاضــي‬\n‫حالــه وعدالتــه‪ -‬بأنــه ثقــة وعــدل ‪ ،‬ومــا يجــري عليــه العمــل يف احملاكــم‬\n‫اليــوم إمنــا هــو زيــادة حتــر فقــط ‪ ،‬وفيمــا يخــص املالحظــة الثانيــة فقــد‬\n‫ســبق أن جــرى االطــاع علــى الالئحــة وقــد قــررت أنــه لــم يظهــر لــي‬\n‫خــاف مــا أجريتــه ‪ ،‬وأنــا مــا زلــت علــى ذلــك ‪ ،‬ومــن بــاب التحــري فقــد‬\n‫حضــر املدعــي ‪ ،‬وأحضــر معــه ‪ /‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم وشــهد بثقــة وعدالــة الشــاهد ‪ ،‬وعليــه فلــم يظهــر خــاف‬\n‫مــا أجريتــه ‪ ،‬وقــررت إحلــاق ذلــك علــى صــك احلكــم وســجله ‪ ،‬وإعــادة‬\n‫املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم بعــد اإلجــراء األخيــر ‪.‬‬\n‫وأقفلــت اجللســة الســاعة ‪ . 12 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/29‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة ففــي يــوم الثالثــاء املوافــق‪ 1434/07/11‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 8 : 45‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫بخطــاب رئيســها رقــم ‪ 331151579‬وتاريــخ ‪1434/7/8‬ه ـ وبالقــرار‬\n‫رقــم ‪ 34256805‬وتاريــخ ‪1434/7/2‬ه ـ ومضمونــه مــا يلــي ‪ :‬وبدراســة‬\n‫احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى‬\n‫احلكــم بعــد اإلجــراء األخيــر جوابـ ًا علــى قــرار الدائــرة رقــم ‪34198378‬‬\n‫يف ‪1434/4/27‬ه ـ وأقفلــت اجللســة الســاعة ‪ 8 :55‬وبــاهلل التوفيــق ‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                             ‫‪ 1434/07/11‬ه ـ‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ فق ــد ج ــرى‬\n‫م ّنــا نح ــن رئيــس وأعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n\n\n                                                                                     ‫‪38‬‬\n\f     ‫االستئناف مبنطقة مك ــة املكرم ــة االطال ُع عل ــى هذا احلكم الصادر‬\n     ‫مــن فضيلــة الشــيخ‪ /‬القاضــي باحملكمــة العامــة بجــدة واملســجل‬\n     ‫بع ــدد‪ 3436038‬وتاريخ ‪1434/2/12‬ه ـ املتضمن دعوى ضد احملكوم‬\n     ‫في ــه مبا دون باطن الصك‪ ،‬وبدراس ــة احلكم وص ــورة ضبط ــه و الئحته‬\n     ‫االعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم بعــد األجــراء األخيــر جوابـ ًا‬\n     ‫علــى قــرار الدائــرة رقــم ‪ 34198378‬يف ‪1434/4/27‬ه ــ‪،‬واهلل املوفــق‪.‬‬\n                      ‫وصل ــى اهلل عل ــى نبينا محمد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪39‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":33,"source_page_end":39,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e77d254d66369994c1be5cd01b307346a831fcec7b5f836123363ad2663a600e","normalized_text_hash":"7bf9896e5457cca886ecdb02a6b129bba39120ef6b85e42a09be743682d0e42f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p33-3436038"},{"id":"9216adaf-0afe-58aa-92f0-6d61a82361e8","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -األصل قول رب املال فيما يبذله من ماله -القضاء باليمن -إلزام املدعى عليه بدفع مبلغ القرض -1األصل قول رب املال فيما يبذله من ماله .","document_number":"3444104","case_number":"3454409","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بخميس مشيط","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/23","year":"1434","subject":"قرض -األصل قول رب املال فيما يبذله من ماله -القضاء باليمن -إلزام املدعى عليه بدفع مبلغ القرض -1األصل قول رب املال فيما يبذله من ماله .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/2/23 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3444104 :‬‬\n                   ‫َر ْق ُم الدعوى‪3454409 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 34194875‬تاريخه‪1434/4/22 :‬هـ‬\n\n\n‫قــرض ‪ -‬األصــل قــول رب املــال فيمــا يبذلــه مــن مالــه ‪ -‬القضــاء‬\n               ‫باليمــن‪ -‬إلــزام املدعــى عليــه بدفــع مبلــغ القــرض‬\n\n\n\n                                ‫‪ -1‬األصل قول رب املال فيما يبذله من ماله ‪.‬‬\n                                                      ‫‪ -2‬القضاء باليمني ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي علــى املدعــى عليــه بأنــه أقرضــه مبلغ ـ ًا مــن املــال يحــل‬\n‫وقــت الطلــب ‪ ،‬طلــب املدعــي إلــزام املدعــى عليــه بدفــع هــذا املبلــغ ‪ ،‬أقــر‬\n‫املدعــى عليــه باســتالم هــذا املبلــغ مــن املدعــي ودفــع بــأن هــذا املبلــغ‬\n‫مــن أجــل املتاجــرة وليــس قرض ـ ًا وأنــه أدخــل هــذا املبلــغ يف البورصــة‬\n‫وذهــب كلــه ‪ ،‬أنكــر املدعــي هــذا الدفــع وذكــر بــأن لديــه محافــظ‬\n‫اســتثماريه يف البنــوك وليــس بحاجــة للمدعــى عليــه ‪ ،‬طلــب القاضــي مــن‬\n‫املدعــى عليــه البينــة علــى دفعــه ‪ ،‬قــرر املدعــى عليــه أنــه ليــس لديــه بينــه‪،‬‬\n‫جــرى إفهامــه بــأن لــه ميــن املدعــي علــى نفــي دفعــه ‪ ،‬قــرر املدعــى عليــه‬\n‫طلــب ميــن املدعــي ‪ ،‬حلــف املدعــي اليمــن ‪ ،‬صــدر احلكــم بإلــزام املدعــى‬\n‫عليــه بدفــع املبلــغ املدعــى بــه للمدعــي ‪ ،‬اعتــرض املدعــي عليــه علــى‬\n‫احلكــم ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪ ،‬مت تنفيــذ احلكــم ‪.‬‬\n\n\n                                                                                           ‫‪40‬‬\n\f     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ؛ وبعــد ‪:‬‬\n     ‫فلــدي أنــا ‪ ...‬املــازم القضائــي لــدى فضيلــة الشــيخ ‪ ...‬مســاعد رئيــس‬\n     ‫احملكمــة العامــة بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n     ‫فضيلــة رئيــس احملكمــة العامــة بخميــس مشــيط برقــم ‪3454409‬‬\n     ‫وتاريــخ ‪ 1434/02/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34270911‬وتاريخ‬\n     ‫‪ 1434/02/03‬ه ـ ففــي يــوم الســبت املوافــق‪ 1434/02/23‬هـ افتتحت‬\n     ‫اجللســة وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫رقــم ‪ ...‬وأدعــى علــى احلاضــر معــه ‪ ...‬ســعودي بالســجل املدنــي رقــم‬\n     ‫ا يف حتريــر دعــواه ‪ :‬بــأن املدعــى عليــه هــذا احلاضــر أقتــرض‬        ‫‪ ...‬قائ ـ ً‬\n     ‫منــي قبــل شــهر رمضــان لعــام ‪1433‬ه ـ مبلغ ـ ًا وقــدره ثمانيــة وعشــرون‬\n     ‫ألفــا وثمامنائــة ريــال ( ‪ 28800‬ريــال ) قرضـ ًا حســن ًا لوجــه اهلل ووعدنــي‬\n     ‫بدفــع هــذا القــرض متــى مــا طلبتــه ولكنــه لــم يقــم بإعــادة هــذا املبلــغ‬\n     ‫ـزءا منــه لــي حتــى اآلن أطلــب إلزامــه بدفــع هــذا املبلــغ هــذه دعــواي‬\n                                                                                 ‫وال جـ ً‬\n     ‫ا‪:‬‬  ‫‪ ،‬وبســؤال املدعــى عليــه عمــا جــاء يف دعــوى املدعــي أجــاب قائ ـ ً‬\n     ‫مــا ذكــره املدعــي يف دعــواه مــن أننــي اقترضــت منــه هــذا املبلــغ فغيــر‬\n     ‫صحيــح والصحيــح أنــه ســلم لــي كامــل هــذا املبلــغ مــن أجــل التجــارة بــه‬\n     ‫يف البورصــة وبعــد أن قمــت بإدخالــه يف هــذه التجــارة لــم أجنــي أي أربــاح‬\n     ‫ـزءا منــه ألن هــذه‬\n                        ‫بــل خســرنا كامــل املبلــغ ولــم أعيــد لــه هــذا املبلــغ أو جـ ً‬\n     ‫جتــارة وهــي عرضــة للربــح واخلســارة وبذلــك فــا يســتحق املبلــغ الــذي‬\n     ‫ا‪:‬‬ ‫يدعــي بــه هكــذا أجــاب ‪ ،‬وبعــرض ذلــك علــى املدعــي أجــاب قائ ـ ً‬\n     ‫مــا ذكــره املدعــى عليــه فغيــر صحيــح ويوجــد لــي محافــظ لــدى البنــوك‬\n\n‫‪41‬‬\n\f‫وأنــا لســت بحاجــة إلــى املتاجــرة مــع املدعــى عليــه ‪ ،‬عندئــذ جــرى ســؤال‬\n‫ا ‪ :‬بأنــه ال‬ ‫املدعــى عليــه هــل لديــه بينــة علــى مــا دفــع بــه ؟ فأجــاب قائ ـ ً‬\n‫بينــة لــي علــى ذلــك ولكننــي أطلــب ميــن املدعــي بــأن هــذا املبلــغ الــذي‬\n‫ســلمه لــي كان علــى وجــه القرضــة احلســنة وليــس علــى وجــه التجــارة‬\n‫‪ ،‬وبعــرض ذلــك علــى املدعــي أســتعد باحللــف علــى مــا أدعــى بــه فأذنــت‬\n‫ا ‪ « :‬واهلل العظيــم الــذي ال إلــه إال‬   ‫لــه بــأداء اليمــن فحلــف بــاهلل قائ ـ ً‬\n‫هــو عالــم الغيــب والشــهادة أن املبلــغ الــذي أعطيتــه هــذا احلاضــر ‪...‬‬\n‫وقــدره ثمانيــة وعشــرون ألــف وثمامنائــة ريــال كان مــن بــاب القرضــة‬\n‫احلســنة وليــس مــن بــاب التجــارة واهلل العظيــم « فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة وحيــث صــادق املدعــى عليــه علــى إســتالمه املبلــغ‬\n‫املدعــى بــه وقــدره ثمانيــة وعشــرون ألــف وثمامنائــة ريــال إال أنــه ال بينــة‬\n‫لــه علــى مــا دفــع بــه مــن أخــذه املــال للتجــارة واألصــل قــول رب املــال فيمــا‬\n‫يبذلــه مــن مالــه وقــد عضــد هــذا األصــل ميــن املدعــي وجلميــع مــا ذكــر‬\n‫فقــد حكمــت علــى املدعــى عليــه ‪ ...‬بــأن يدفــع للمدعــي ‪ ...‬مبلغــا وقــدره‬\n‫ثمانيــة وعشــرون ألفــا وثمامنائــة ريــال(‪ 28800‬ريــال) ؛ وبعــرض احلكــم‬\n‫علــى املدعــى عليــه ؛ قــرر عــدم القناعــة وطلــب يف متكينه مــن اإلعتراض‬\n‫عليــه فأجيــب لطلبــه ؛ وأمــرت بتزويــده بصــورة مــن صــك احلكــم يف‬\n‫هــذا اليــوم الســبت ‪1434/02/23‬ه ـ وأفهمتــه بــأن عليــه تقــدمي االئحــة‬\n‫اإلعتراضيــة يف املــدة النظاميــة وهــي ثالثــون يومــا تبــدأ مــن تاريــخ‬\n‫هــذا اليــوم وإذا لــم يقــدم اعتراضــه خــال هــذه املــدة ســقط حقــه يف‬\n‫طلــب اإلســتئناف واكتســب احلكــم القطعيــة ففهــم ذلــك وعليــه جــرى‬\n‫التوقيــع ثــم جــرى رفــع اجللســة ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n          ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/23‬ه ـ ‪.‬‬\n\n\n                                                                                            ‫‪42‬‬\n\f     ‫احلمــد هلل وحــده وبعــد ‪ ..‬ففــي يــوم االثنــن املوافــق ‪1434/05/06‬ه ـ‬\n     ‫افتتحــت اجللســة يف متــام الســاعة ‪ 01 : 45‬وقــد وردتنــا املعاملــة مــن‬\n     ‫محكمــة االســتئناف برقــم ‪ 34780073‬وتاريــخ ‪1434/04/28‬ه ـ‬\n     ‫وبرفقهــا القــرار ذي الرقــم ‪ 34194875‬وتاريــخ ‪1434/04/22‬ه ـ‬\n     ‫الصــادرة مــن الدائــرة احلقوقيــة الثالثــة واملــدون علــى ظهــر الصــك رقــم‬\n     ‫‪ 3444104‬وتاريــخ ‪1434/02/23‬ه ـ املتضمــن املوافقــة علــى احلكــم‬\n     ‫واملوقــع عليــه مــن قاضــي اســتئناف ‪ ...‬توقيعــه وختمــه وقاضــي‬\n     ‫اســتئناف ‪ ...‬توقيعــه وختمــه ورئيــس الدائــرة ‪ ...‬توقيعــه وختمــه وللبيــان‬\n     ‫جــرى إحلاقــه ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                              ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/06‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬مســاعد رئيــس احملكمــة‬\n     ‫العامــة بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n     ‫رئيــس احملكمــة العامــة بخميــس مشــيط برقــم ‪ 3454409‬وتاريــخ‬\n     ‫‪ 1434/02/03‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34270911‬وتاريــخ‬\n     ‫‪ 1434/02/03‬ه ـ ففــي يــوم الســبت املوافــق‪ 1434/07/01‬ه ـ افتتحت‬\n     ‫وفيهــا حضــر املدعــي ‪ ...‬ســعودي بالســجل املدنــي رقــم ‪ ...‬وقــرر بقولــه ‪:‬‬\n     ‫بأننــي إســتلمت كامــل املبلــغ احملكــوم بــه لــي وقــدره ثمانيــة وعشــرون‬\n     ‫ألــف وثمامنائــة ريــال ‪ ،‬ولــم يعــد لــي أي مطالبــة علــى املدعــى عليــه بهــذا‬\n     ‫الشــأن هكــذا قــرر ‪ ،‬لــذا جــرى إحلاقــه بضبطــه وأمــرت بالتهميــش‬\n     ‫علــى صكــه وســجله بذلــك ‪ ،‬ثــم رفعــت اجللســة وعليــه جــرى التوقيــع‬\n     ‫‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                              ‫وســلم ‪ .‬حــرر يف ‪1434/07/01‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة الثالثــة‬\n\n\n‫‪43‬‬\n\f‫مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة بخميــس مشــيط برقــم ‪ 34730322‬وتاريــخ‬\n‫‪1434/3/23‬ه ـ اخلاصــة بدعــوى ‪ ... /‬ضــد‪ ... /‬بشــأن مبلــغ مالــي املرفــق‬\n‫بهــا الصــك الصــادر مــن فضيلــة املــازم القضائــي الشــيخ‪ ... /‬برقــم‬\n‫‪ 3444104‬وتاريــخ ‪1434/2/23‬ه ـ املتضمــن حكــم فضيلتــه مبــا‬\n‫هــو مــدون ومفصــل فيــه وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة لــم يظهــر مــا يوجــب االعتــراض لــذا قررنــا‬\n‫املوافقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                           ‫آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪44‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":40,"source_page_end":44,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3b942bcec4ff2cb533d121cdc6c9caaa17398d54a98d41c72dc1a0ec32ce9556","normalized_text_hash":"63d0598b53889fbcdef7d07906021e7d2f8660ce293ebee24db2452956e0e5c5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p40-3444104"},{"id":"14b5f808-0d0a-57e5-974f-750b4e7b17bf","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -تخلف املدعى عليه عن احلضور -اإلعالن عن موعد اجللسة يف اجلريدة -طلب املدعى عليه عن طريق اإلمارة -اليمن تشرع يف جانب أقوى املتداعين -احلكم الغيابي -احلكم على املدعى عليه -الغائب على حجته متى حضر .","document_number":"3455626","case_number":"3426635","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/4","year":"1434","subject":"قرض -تخلف املدعى عليه عن احلضور -اإلعالن عن موعد اجللسة يف اجلريدة -طلب املدعى عليه عن طريق اإلمارة -اليمن تشرع يف جانب أقوى املتداعين -احلكم الغيابي -احلكم على املدعى عليه -الغائب على حجته متى حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/3/4 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪3455626 :‬‬\n                        ‫َر ْق ُم الدعوى‪3426635 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34228119‬تاريخه‪1434/6/3 :‬هـ‬\n\n\n     ‫قــرض ‪ -‬تخلــف املدعــى عليــه عن احلضور ‪-‬اإلعالن عن موعد اجللســة‬\n     ‫يف اجلريــدة ‪ -‬طلــب املدعــى عليــه عــن طريــق اإلمــارة ‪ -‬اليمــن تشــرع‬\n     ‫يف جانــب أقــوى املتداعيــن ‪ -‬احلكــم الغيابــي‪ -‬احلكــم علــى املدعــى‬\n                                   ‫عليــه ‪ -‬الغائــب علــى حجتــه متــى حضــر ‪.‬‬\n\n\n\n            ‫‪ -1‬قوله تعالى ‪( :‬إن اهلل يأمركم أن تؤدوا األمانات إلى أهلها )‪.‬‬\n     ‫‪ -2‬قولــه صلــى اهلل عليــه وســلم ‪( :‬علــى اليــد مــا أخــذت حتــى تؤديــه )‪.‬‬\n                                                   ‫رواه أحمــد و أصحــاب السـن ــن‪.‬‬\n\n\n\n\n     ‫ادعــى املدعــي وكالــة علــى املدعــى عليــه الغائــب بــأن موكلــه أقرضــه‬\n     ‫قرضــه حســنه و أن املدعــى عليــه لــم يســدد مــن هــذه القرضــة شــيئ ًا‬\n     ‫‪ -‬جــرى طلــب املدعــى عليــه عــن طريــق األمــارة و االعــان يف اجلريــدة ‪-‬‬\n     ‫اســتمر املدعــى عليــه علــى تخلفــه ‪ -‬أبــرز املدعــى وكالــة ســند القــرض‬\n     ‫وجــرى رصــده ‪ -‬حيــث إن اليمــن تشــرع يف جانــب أقــوى املتداعيــن لــذا‬\n     ‫جــرى طلــب املدعــي أصالــة ‪ -‬حلــف املدعــي أصالــة علــى صحــه دعــواه ‪-‬‬\n     ‫صــدر احلكــم غيابيـ ًا علــى املدعــى عليــه بدفــع املبلــغ املدعــى بــه ‪ -‬جــرى‬\n     ‫التنويــه يف منطــوق احلكــم بــأن املدعــى عليــه الغائــب علــى حجتــه متــى‬\n\n‫‪45‬‬\n\f                      ‫حضــر ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 3246635‬وتاريــخ ‪1432/9/13‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 32142579‬وتاريــخ ‪1432/9/13‬هـ ففي يوم األربعاء‬\n‫املوافــق ‪1433/1/12‬ه ـ حضــر ‪ ...‬ســعودي مبوجــب ســجل مدنــي رقــم‬\n‫(‪ ) ...‬بصفتــه وكيــا عــن ‪ ...‬ســعودي مبوجــب ســجل مدنــي رقــم (‪) ...‬‬\n‫ينــوب عــن موكلــه يف املطالبــة واملرافعــة واملدافعــة واملخاصمــة وإقامــة‬\n‫الدعــاوى ضــد الغيــر ولــه احلــق يف ســماع الدعــوى والــرد عليهــا واإلقــرار‬\n‫واإلنــكار والصلــح مبوجــب صــك وكالــة صــادر مــن كتابــة العــدل‬\n‫الثانيــة بالريــاض برقــم ‪ 2428‬يف ‪1433/1/9‬ه ـ بصفتــه وكيــا عــن ‪...‬‬\n‫ســعودي مبوجب ســجل مدني رقم (‪ ) ...‬مبوجب صك وكالة صادر من‬\n‫كتابــة العــدل الثانيــة بشــرق الريــاض برقــم ‪ 15511‬يف ‪1432/2/14‬ه ـ‬\n‫ولــم يحضــر املدعــى عليــه ‪ ...‬ســعودي مبوجــب ســجل مدنــي رقــم (‪) ...‬‬\n‫ووردنــا خطــاب مديــر مركــز شــرطة الســليمانية رقــم ‪15/6/373/2‬‬\n‫يف ‪1433/1/10‬ه ـ املتضمــن‪ :‬نفيــد فضيلتكــم أنــه تبلــغ املذكــور عــدة‬\n‫مــرات ملراجعتنــا ولــم يتجــاوب باحلضــور ا‪.‬ه ـ لــذا رفعــت اجللســة لطلــب‬\n‫حضــور املدعــى عليــه ‪ .‬ويف يــوم الســبت املوافــق ‪1433/05/15‬ه ـ حضــر‬\n‫‪ ...‬ســعودي مبوجــب ســجل مدنــي رقــم (‪ ) ...‬بصفتــه وكيــا عــن ‪...‬‬\n‫ســعودي مبوجــب ســجل مدنــي رقــم (‪ ) ...‬ينــوب عنــه يف املطالبة واملرافعة‬\n‫واملدافعــة واملخاصمــة وإقامــة الدعاوى ضد الغير وســماع الدعوى والرد‬\n\n                                                                                    ‫‪46‬‬\n\f     ‫عليهــا واإلقــرار واإلنــكار والصلــح مبوجــب صــك وكالــة صــادر مــن‬\n     ‫كتابــة العــدل الثانيــة بالريــاض برقــم ‪ 15511‬يف ‪1432/02/14‬ه ـ ولــم‬\n     ‫يحضــر املدعــى عليــه ‪ ...‬املــدون هويتــه ســابقا ومبــا أن املدعــي ال يعــرف‬\n     ‫عنوانــه جــرت الكتابــة إلــى وكيــل إمــارة منطقــة الريــاض بخطابنــا‬\n     ‫رقــم ‪ 33103113‬وتاريــخ ‪1433/1/23‬ه ـ للبحــث والتحــري عــن املدعــى‬\n     ‫عليــه وإبالغــه باحلضــور لهــذه اجللســة ولــم تــرد إفــادة‪ .‬ويف يــوم األربعــاء‬\n     ‫املوافق‪1433/10/25‬ه ـ حضــر املدعــي وكالــة ‪ ...‬ولــم يحضــر املدعــى‬\n     ‫عليــه ‪ ...‬املــدون هويتــه ســابقا وأبــرز املدعــي أصــل اإلعــان عــن موعــد‬\n     ‫هــذه الدعــوى يف جريــدة ‪ ...‬عــدد رقــم ‪ 14551‬صفحــة ‪ 32‬وبســؤال‬\n     ‫املدعــي عــن دعــواه أجــاب قائــا ‪ :‬ســبق أن أقــرض موكلــي املدعــى‬\n     ‫عليــه مبلغــا و قــدره ســتة و ثالثــون ألــف ريــال يف ‪1431/02/29‬هـ والزال‬\n     ‫يف ذمتــه و أطلــب إلزامــه بســداده ملوكلــي هــذه دعــواي وبســؤاله عــن‬\n     ‫بينتــه أبــرز ورقــة هــذا نصهــا ‪ :‬نعــم أنــا ‪ ...‬رقــم البطاقــة (‪ ) ...‬مصدرهــا‬\n     ‫الريــاض تاريخــه ‪1399/08/02‬ه ـ نعــم يف ذمتــي مبلــغ و قــدره تســعة‬\n     ‫و ثالثــون ألــف ريــال ســعودي ال غيــر ‪ +‬خمســمائة ريــال يتــم تســديد‬\n     ‫املبلــغ إلــى األخ ‪ ...‬يف نهايــة شــهر ذي القعــدة ولــه احلــق املطلــوب قبــل‬\n     ‫املوعــد املذكــور املقــر مبــا فيــه ‪ ...‬توقيعــه بتاريــخ ‪1431/02/29‬ه ـ ‪.‬‬\n     ‫أ‪.‬ه ـ و بســؤاله هــل لديــه زيــادة بينــة أجــاب قائــا ‪ :‬ليــس لــدي زيــادة بينــة‬\n     ‫هكــذا أجــاب لــذا أفهمــت املدعــي وكالــة بإحضــار موكلــه فاســتعد‬\n                                                            ‫بذلــك يف اجللســة القادمــة‪.‬‬\n     ‫ويف يــوم األربعــاء املوافــق‪ 1434/03/04‬ه ـ حضــر املدعــي أصالــة ‪...‬‬\n     ‫ســعودي مبوجــب ســجل مدنــي رقــم (‪ ) ...‬واملدعــي وكالــة ‪ ...‬ولــم يحضر‬\n     ‫املدعــى عليــه ‪ ...‬وبطلــب اليمــن علــى املدعــي أصالــة حلــف قائــا‪ :‬واهلل‬\n\n\n‫‪47‬‬\n\f‫العظيــم الــذي ال إلــه إال هــو أننــي ســبق أن أقرضــت املدعــى عليــه مبلغــا‬\n                                                           ‫خمسمائة ريال يف ‪1431/02/29‬هـ‬\n‫وال زال يف ذمتــه هكــذا حلــف‪ .‬فبنــاء علــى مــا تقــدم مــن ســماع الدعــوى‬\n‫غيابيــا وخطــاب مديــر مركــز شــرطة الســليمانية رقــم ‪15/6/373/2‬‬\n‫يف ‪1433/1/10‬ه ـ املتضمــن أنــه تبلــغ املذكــور عــدة مــرات باملراجعــة‬\n‫ولــم يتجــاوب باحلضــور واإلعــان عــن هــذه الدعــوى ومــا أبــرزه املدعــي‬\n‫وكالــة مــن إقــرار منســوب للمدعــى عليــه كل ذلــك يقــوي جانــب‬\n‫املدعــي ومبــا أن اليمــن تشــرع يف جانــب أقــوى املتداعيــن وقــد حلــف‬\n‫املدعــي أصالــة اليمــن علــى دعــواه ولقولــه تعالــى‪( :‬إن اهلل يأمركــم‬\n‫أن تــؤدوا األمانــات إلــى أهلهــا) والقــرض أمانــة عنــد املقتــرض يجــب‬\n‫عليــه ردهــا إلــى صاحبهــا ولقولــه صلــى اهلل عليــه وســلم (علــى اليــد‬\n‫مــا أخــذت حتــى تؤديــه) رواه أحمــد وأصحــاب الســن األربعــة ومبــا أن‬\n‫الغائــب علــى حجتــه متــى حضــر لــذا فقــد ألزمــت املدعــى عليــه الغائــب‬\n‫أن يدفــع للمدعــي أصالــة املبلــغ املدعــى بــه وقــدره ســتة وثالثــون ألــف‬\n‫وخمســمائة ريــال والغائــب علــى حجتــه متــى حضــر ومبــا تقــدم حكمــت‬\n‫وهــذا احلكــم غيابــي وأمــرت بإخــراج صــك مبوجبــه وإبــاغ احملكــوم‬\n‫عليــه بصورتــه لتقريــر قناعتــه أو معارضتــه وتقدميهــا خــال ثالثــن يومــا‬\n‫فــإن مضــت املــدة ولــم يقــدم الئحــة اعتراضــه بعــد تبلغــه ســقط حقــه يف‬\n‫االعتــراض واكتســب احلكــم القطعيــة ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/03/04‬‬\n                                                                               ‫هـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة السادســة‬\n‫لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n\n\n                                                                           ‫‪48‬‬\n\f     ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد برقــم‬\n     ‫‪ 321183852‬وتاريــخ ‪1434/5/25‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n     ‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ ... /‬املســجل برقــم ‪3455626‬‬\n     ‫وتاريــخ ‪1434/3/4‬ه ـ اخلــاص بدعــوى ‪ ... /‬وكالــة عــن ‪ ...‬ضــد ‪ ... /‬يف‬\n     ‫مبلــغ مالــي علــى الصفــة املوضحــة بالصــك واملتضمــن أن فضيلتــه ألــزم‬\n     ‫املدعــى عليــه الغائــب أن يدفــع للمدعــي أصالــة املبلــغ املدعــى بــه وقــدره‬\n     ‫ســتة وثالثــون ألف ـ ًا وخمســمائة ريــال والغائــب علــى حجتــه متــى حضــر‬\n     ‫ومبــا تقــدم حكــم حكم ـ ًا غيابي ـ ًا ‪،‬وبدراســة الصــك وصــورة ضبطــه‬\n     ‫وأوراق املعاملــة قررنــا باألكثريــة املصادقــة علــى احلكــم ‪.‬والل ــه املوفــق‬\n                            ‫وصلــى اهلل علــى نبينــا محمـ ــد وآل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪49‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":45,"source_page_end":49,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"97566fb13eb29c1f8296bee65ab4946e8ab811a06d2491a4f8895da168162c25","normalized_text_hash":"7df8831638a3553dfccb7315c093135d6b5a630ba5b4dec8b7b579f6d2ed47d9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p45-3455626"},{"id":"7ac74915-ef64-5bb5-9f3d-2a7dfb650028","document_type":"judgment","category":"judicial","subcategory":"general","title":"إقراض -مال مقبوض -قيام املدعي بتسليم مبلغ مالي للمدعي عليه -طلب املدعي إلزام املدعى عليه بإعادة هذا املبلغ -حجية السندات الرسمية -األوراق الصادرة من كتاب العدل تكون لها قوة اإلثبات وال يجوز الطعن فيها -إلزام املدعى عليه بدفع املبلغ املدعى به للمدعي.","document_number":"34168512","case_number":"32382274","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/22","year":"1434","subject":"إقراض -مال مقبوض -قيام املدعي بتسليم مبلغ مالي للمدعي عليه -طلب املدعي إلزام املدعى عليه بإعادة هذا املبلغ -حجية السندات الرسمية -األوراق الصادرة من كتاب العدل تكون لها قوة اإلثبات وال يجوز الطعن فيها -إلزام املدعى عليه بدفع املبلغ املدعى به للمدعي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/3/22 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34168512 :‬‬\n                   ‫َر ْق ُم الدعوى‪32382274 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34209665‬تاريخه‪1434/5/8 :‬هـ‬\n\n\n\n‫إقــراض ‪ -‬مــال مقبــوض ‪ -‬قيــام املدعــي بتســليم مبلــغ مالــي للمدعــي‬\n‫عليــه ‪ -‬طلــب املدعــي إلــزام املدعــى عليــه بإعــادة هــذا املبلــغ ‪ -‬حجيــة‬\n‫الســندات الرســمية ‪ -‬األوراق الصــادرة مــن كتــاب العــدل تكــون لهــا‬\n‫قــوة اإلثبــات وال يجــوز الطعــن فيهــا ‪ -‬إلــزام املدعــى عليــه بدفــع املبلــغ‬\n                                                          ‫املدعــى بــه للمدعــي‪.‬‬\n\n\n\n\n‫‪ -1‬قــال يف شــرح منتهــى اإلرادات (‪ )295/4‬وكشــاف القنــاع (‪:)218/4‬‬\n‫(يعمــل بســجالت احملكمــة املصونــة حتــت أيــدي القضــاة إذا كانــت‬\n                               ‫ســاملة مــن شــبهتي التزويــر واحليلــة) ‪.‬‬\n‫‪ -2‬املــادة (‪ )80‬مــن نظــام القضــاء والتــي نصت على (أن األوراق الصادرة‬\n‫مــن كتــاب العــدل تكــون لهــا قــوة اإلثبــات ‪ ،‬ويجــب العمــل مبضمونهــا‬\n‫أمــام احملاكــم بــا بينــة إضافيــة ‪ ،‬وال يجــوز الطعــن فيهــا إال تأسيسـ ًا‬\n‫علــى مخالفتهــا ملقتضــى األصــول الشــرعية أو النظاميــة أو تزويرهــا) ‪.‬‬\n\n\n\n\n‫أقــام املدعــي دعــواه ضــد املدعــى عليــه «شــقيقه» طالبـ ًا إلزامــه بــرد مبلــغ‬\n‫وقــدرة مائــة وخمســة آالف ريــال قــام باعطائهــا لــه بنــاء علــى طلبــه ولــم‬\n\n                                                                                        ‫‪50‬‬\n\f     ‫يرجــع لــه هــذا املبلــغ حتــى اآلن ومبواجهــة املدعــى عليــه بذلــك قــال إن‬\n     ‫هــذا املبلــغ لقــاء بيعــي لــه قطعــة أرض وإشــرايف علــى عمارتــه القائمــة‬\n     ‫علــى تلــك األرض ورد املدعــى علــى ذلــك بــأن األرض املذكــورة قــد‬\n     ‫جــرى ســداد ثمنهــا نقــد ًا وقــدم صــك ًا مــن كاتــب عــدل مذكــور بــه‬\n     ‫أن املدعــى عليــه أســتلم مبلــغ أربعــن ألــف ريــال قيمــة األرض ولكــون‬\n     ‫مــا يوثــق لــدى كاتــب العــدل حجــة يف اإلثبــات قــررت احملكمــة إلــزام‬\n     ‫املدعــى عليــه بــرد مبلــغ وقــدره مائــة وخمســة آالف ريــال إلــى املدعــى‬\n     ‫وقــد أعتــرض املدعــى عليــه علــى احلكــم وجــرى تصديقــه مــن محكمــة‬\n                                                                      ‫االســتئناف ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد يف يــوم الثالثــاء املوافــق ‪1433/1/25‬ه ـ لــدي‬\n     ‫أنــا ‪ .......‬القاضــي يف احملكمــة العامــة بعنيــزة افتتحــت اجللســة يف‬\n     ‫وقتهــا احملــدد لســماعها يف الســاعة احلاديــة عشــر صباحــا للنظــر يف‬\n     ‫الدعــوى املقدمــة مــن ‪ .......‬ضــد ‪ .......‬واملقيــدة يف هــذه احملكمــة‬\n     ‫برقــم ‪ 321120998‬يف ‪1432/8/29‬ه ـ واحملالــة لنــا بشــرح فضيلــة‬\n     ‫الرئيــس وقــد افتتحــت هــذه اجللســة بنــاء علــى املــادة اخلامســة واخلمســن‬\n     ‫مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة وفيهــا حضــر ‪.......‬‬\n     ‫ســعودي مبوجــب الســجل رقــم ‪ .......‬الوكيــل عــن أخيــه ‪ .......‬ســعودي‬\n     ‫بالســجل رقــم ‪ .......‬الوكالــة الصــادرة مــن كاتــب عــدل عنيــزة برقــم‬\n     ‫‪ 32144631‬يف ‪1432/6/26‬ه ـ وادعــى علــى الغائــب عــن مجلــس‬\n     ‫القضــاء ‪ .......‬الــذي تبلــغ بهــذا املوعــد لشــخصه حســبما يظهــر مــن‬\n     ‫ورقــة التبليــغ املرفقــة باملعاملــة قائــا يف حتريــر دعــواه لقــد قــام املدعــى‬\n\n‫‪51‬‬\n\f‫عليــه باحلضــور إلــى موكلــي يف منزلــه ‪ ...‬ثــم ذهــب بــه إلــى صنــدوق‬\n‫التنميــة العقاريــة ‪ ...‬ثــم اســتلم موكلــي الدفعــة الثالثــة مــن القــرض الــذي‬\n‫نــزل باســمه وقــدره مائــة وخمســة آالف ريــال ثــم قــام بتســليم هــذا املبلــغ‬\n‫كامــا للمدعــى عليــه بطلــب منــه ولكــن لــم يعــد لــه هــذا املبلــغ حتــى‬\n‫اآلن أطلــب إلــزام املدعــى عليــه بــأن يســلم ملوكلــي املبلــغ الــذي اســتلمه‬\n‫منــه وقــدره مائــة وخمســة آالف ريــال هــذه دعــواي ثــم ســألت املدعــي‬\n‫وكالــة هــل قــام موكلــك باســتالم هــذا املبلــغ املدعــى بــه مــن الصنــدوق‬\n‫نقــدا أو مبوجــب شــيك فقــال إننــي ال أعلــم وأطلــب إمهالــي للرجــوع إلــى‬\n‫موكلــي وســؤاله عــن ذلــك فأمهــل لذلــك ثــم رفعــت اجللســة ثــم يف جلســة‬\n‫أخــرى حضــر املدعــي وكالــة ‪ .......‬ولــم يحضــر املدعــى عليــه ثــم ســألت‬\n‫املدعــي وكالــة عمــا جــرى ســؤاله عنــه يف اجللســة الســابقة فقــال إن‬\n‫موكلــي اســتلم هــذا املبلــغ املدعــى بــه مــن صنــدوق التنميــة العقاريــة‬\n‫نقــدا ثــم رفعــت اجللســة ثــم يف جلســة أخــرى حضــر املدعــي وكالــة ‪.......‬‬\n‫كمــا حضــر املدعــى عليــه ‪ .......‬ســعودي مبوجــب الســجل املدنــي رقــم‬\n‫‪ .......‬ثــم جــرى تــاوة الدعــوى عليــه وســؤاله اجلــواب فأجــاب قائــا مــا‬\n‫ذكــره املدعــي وكالــة مــن إســتالمي مبلغــا وقــدره مائــة وخمســة األف‬\n‫ريــال وهــي الدفعــة الثالثــة مــن القــرض الــذي اســتلمه املدعــي أصالــة‬\n‫‪ .......‬فهــذا صحيــح وقــد اســتلمته نقــدا ثــم قــرر قائــا إننــي أطلــب‬\n‫إمهالــي إلحضــار جوابــي محــررا كــي أبــن فيــه التعامــات املاليــة التــي‬\n‫حصلــت بينــي وبــن أخــي املدعــي أصالــة ‪ .......‬ومقــدار مســتحقاتي‬\n‫لديــه لقــاء شــرائه منــي أرض وقيامــي باإلشــراف علــى عمارتــه القائمــة‬\n‫علــى تلــك األرض فأجيــب لذلــك ثــم رفعــت اجللســة ثــم يف جلســة أخــرى‬\n‫حضــر املدعــي وكالــة ‪ .......‬واملدعــى عليــه ‪ .......‬ثــم قــرر املدعــى‬\n\n\n                                                                                       ‫‪52‬‬\n\f     ‫عليــه قائــا إننــي لــم أســتطيع إحضــار جوابــي محــررا ولكــن جوابــي‬\n     ‫هــو أننــي اســتلمت املبلــغ املدعــى بــه لقــاء تنازلــي عــن األرض اململوكــة‬\n     ‫لــي مبوجــب الصــك الصــادر مــن كتابــة عــدل عنيــزة برقــم ‪ .......‬يف‬\n     ‫‪1417/08/29‬ه ـ ألخــي املدعــي أصالــة ‪ .......‬ولــذا فإننــي أطلــب رد‬\n     ‫هــذه الدعــوى هــذا هــو جوابــي وبعــرض ذلــك علــى املدعــي وكالــة قــال‬\n     ‫مــا ذكــره املدعــى عليــه غيــر صحيــح نظــرا ألنــه لــم يتنــازل عــن هــذه‬\n     ‫األرض تنــازال بــا مقابــل بــل باعهــا علــى موكلــي بثمــن مقبــوض قــدره‬\n     ‫أربعــون ألــف ريــال بتاريــخ ‪1429/10/22‬ه ـ وبعــرض ذلــك علــى املدعــى‬\n     ‫عليــه قــال صحيــح أنــه أثبــت لــدى كاتــب العــدل أننــي بعــت هــذه األرض‬\n     ‫اململوكــة بذلــك الصــك بثمــن مقبــوض قــدره أربعــون ألــف ريــال لكــن‬\n     ‫احلقيقــة أننــي لــم أســتلم شــيئا مــن قيمتهــا هكــذا أجــاب ثــم جــرى إفهــام‬\n     ‫املدعــي وكالــة بــأن عليــه إحضــار أصــل الصــك املشــار إليــه يف الدعــوى‬\n     ‫مــع اجلــواب ففهــم ذلــك واســتعد بــه وطلــب إمهالــه إلــى جلســة أخــرى‬\n                                                 ‫فأجيــب لذلــك ثــم رفعــت اجللســة‪.‬‬\n     ‫ثــم يف جلســة أخــرى حضــر املدعــي وكالــة ‪ .......‬ولــم يحضــر املدعــى‬\n     ‫عليــه ‪ .......‬ولــم يقــدم عــذرا لتخلفــه عــن احلضــور بهــذا املعــد يف ضبــط‬\n     ‫القضيــة ثــم أبــرز املدعــي وكالــة أصــل الصــك الصــادر مــن كتابــة‬\n     ‫عــدل عنيــزة برقــم ( ‪ ) .......‬يف (‪1417/8/29‬ه ـ ) واملثبــت فيــه متلــك‬\n     ‫‪ .......‬ســعودي بالســجل املدنــي رقــم ‪ .......‬لقطعــة األرض رقــم ‪ .......‬مــن‬\n     ‫املخطــط رقــم ‪ .......‬يف ‪1392/6/13‬ه ـ بحــي ‪ .......‬بعنيــزة احملــدودة‬\n     ‫شــماال مواقــف ســيارات بطــول (‪ )22.50‬م وجنوبــا قطعــة رقــم (‪)352‬‬\n     ‫بطــول (‪ )23‬م وشــرقا شــارع عرضــه (‪ )18‬م بطــول (‪ )30‬وغربــا قطعــة‬\n     ‫رقــم (‪ )338‬بطــول (‪ )30‬م ومجمــوع مســاحتها ســتمائة واثنــان وثمانــون‬\n\n\n‫‪53‬‬\n\f‫متــرا مربعــا وخمســون ســنتمترا مربــع وقــد انتقلــت إليــه بالشــراء مــن‬\n‫مالكهــا مببلــغ قــدره خمســة وأربعــون ألــف ريــال وقــد همــش علــى هــذا‬\n‫الصــك بإنتقــال هــذه القطعــة إلــى ملكيــة‪ .......‬ســعودي بالســجل رقــم‬\n‫‪ .......‬بالشــراء مــن ‪ .......‬بثمــن قــدره أربعــون ألــف ريــال نقــدا كمــا‬\n‫همــش عليــه بأنــه مت رهنــه لصالــح صنــدوق التنميــة العقاريــة مقابــل‬\n‫مبلــغ قــدرة ثالثمائــة ألــف ريــال أ‪ .‬ه ـ ثــم رفعــت اجللســة ثــم يف جلســة‬\n‫أخــرى حضــر املدعــي وكالــة ‪ .......‬واملدعــى عليــه ‪ .......‬وقــد جــرى منــا‬\n‫تأمــل هــذه القضيــة ودراســتها وبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة‬\n‫ونظــرا إلقــرار املدعــى عليــه بإســتالمه للمبلــغ املدعــى بــه وقــدره مائــة‬\n‫وخمســة آالف ريــال مــن املدعــي أصالــة ودفعــه بــأن ذلــك لقــاء تنازلــه عــن‬\n‫األرض اململوكــة لــه مبوجــب الصــك رقــم ( ‪ ) .......‬يف (‪1417/8/29‬هـ )‬\n‫ألخيــه املدعــي أصالــة ‪ .......‬ونظــرا إلرتــكاز املدعــي وكالــة ملــا جــاء يف‬\n‫دفــع املدعــى عليــه مدعيــا أن املدعــى عليــه لــم يتنــازل عــن هــذه األرض‬\n‫بــا مقابــل بــل باعهــا علــى موكلــه مببلــغ قــدره أربعــون ألــف ريــال ثــم‬\n‫مصادقــة املدعــى عليــه علــى ذلــك ودفعــه بأنــه لــم يســتلم مــن قيمتهــا‬\n‫شــيئا وألنــه جــرى اإلطــاع علــى أصــل الصــك املذكــور وقــد جــاء فيــه‬\n‫إنتقــال ملكيــة األرض املوصوفــة فيــه إلــى املدعــي أصالــة ‪ .......‬بالشــراء‬\n‫مــن املدعــى عليــه ‪ .......‬بثمــن قــدره أربعــون ألــف ريــال نقــدا كمــا هــو‬\n‫مــدون بالتفصيــل يف اجللســة املنعقــدة يف ‪1433/10/28‬ه ـ ونظرا ملا جاء‬\n‫يف املــادة (‪ )80‬مــن نظــام القضــاء التــي نصــت علــى أن األوراق الصــادرة‬\n‫مــن كتــاب العــدل تكــون لهــا قــوة اإلثبــات ويجــب العمــل مبضمونهــا‬\n‫أمــا احملاكــم بــا بينــة إضافيــه وال يجــوز الطعــن فيهــا إال تأسيســا علــى‬\n‫مخالفتهــا ملقتضــى األصــول الشــرعية أو النظاميــة أو تزويرهــا أ‪ .‬ه ـ ‪.‬‬\n\n\n                                                                                     ‫‪54‬‬\n\f     ‫وممــا يؤكــد هــذا املعنــى مــا نــص عليــه صاحــب شــرح منتهــى اإلرادات‬\n     ‫(‪ )295/4‬وصاحــب كشــاف القنــاع (‪ )218/4‬حيــث قــاال مــا نصــه‬\n     ‫((يعمــل بســجالت احملكمــة املصونــة حتــت أيــدي القضــاة إذا كانــت‬\n     ‫ســامله مــن شــبهتي التزويــر واحليلــة )) أ ‪ .‬ه ـ ‪ .‬وهــذا يــدل علــى أن دفــع‬\n     ‫املدعــى عليــه ليــس لــه وجــه ال ســيما إذا كان ثمــن األرض املوصوفــه يف‬\n     ‫هــذا الصــك أربعــون ألــف ريــال واملبلــغ املدعى به أكثر مــن ذلك بكثير‬\n     ‫كمــا أن ثمــن األرض همــش بكــون إســتالمه نقــدا وألنــه ليــس هنــاك‬\n     ‫حاجــة لإلستفســار عــن ســريان مفعول ســجل الصك املذكــور يف جواب‬\n     ‫املدعــى عليــه نظــرا ألن اخلــاف بــن املتداعــن ليــس يف متلــك األرض‬\n     ‫لذلــك كلــه فقــد ألزمــت املدعــى عليــه ‪ .......‬بــأن يدفــع للمدعــي أصالــة‬\n     ‫‪ .......‬املبلــغ املدعــى بــه وقــدره مائــة وخمســة آالف ريــال وبذلــك حكمــت‬\n     ‫وبعرضــه عليهمــا قنــع بــه املدعــي وكالــة ولــم يقنــع بــه املدعــى عليــه‬\n     ‫وطالــب بتمييــزه فأجيــب لطلبــه ثــم جــرى تســليمه نســخة مــن احلكم ومت‬\n     ‫إفهامــه بــأن عليــه تســليم الئحتــه اإلعتراضيــه يف مــدة أقصاهــا ثالثــون‬\n     ‫يومــا مــن تاريــخ هــذا اليــوم وأنــه إذا مضــت هــذه املــدة احملــددة آنفــا‬\n     ‫ولــم يقــدم فيهــا إعتراضــه فــإن حقــه يف طلــب التمييــز يســقط ويصبــح‬\n     ‫احلكــم مكتســبا القطعيــة فقــرر إســتالمه لنســخة احلكــم وفهمــه ملــا‬\n     ‫أفهــم بــه آنفــا وإســتعداده بتقــدمي الئحتــه اإلعتراضيــه يف املــدة احملــددة‬\n     ‫نظامــا وعليــه جــرى التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/03/22‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد يف يــوم الثالثــاء املوافــق ‪1434/5/21‬ه ـ افتتحــت‬\n     ‫اجللســة يف الســاعة احلاديــة عشــر والنصــف صباحــا بنــاء علــى ورود‬\n     ‫املعاملــة مــن محكمــة االســتئناف بالقصيــم برقــم (‪)341026524‬‬\n\n\n‫‪55‬‬\n\f‫يف ‪1434/5/14‬ه ـ مــزود بقــرار أصحــاب الفضيلــة قضــاة االســتئناف‬\n‫بالدائــرة احلقوقيــة األولــى مبحكمــة االســتئناف بالقصيــم رقــم‬\n‫(‪ )34209665‬يف ‪1434/5/8‬ه ـ املقــرر فيــه املصادقــة علــى احلكم أ‪.‬هـ‪.‬‬\n‫وقــد جــرى التهميــش بذلــك حســب التعليمــات و عليــه جــرى التوقيــع ‪.‬‬\n                                                   ‫حــرر يف ‪ 1434/05/21‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وعلى آلــه وصحبه‬\n‫وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مبنطقــة القصيــم علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n‫ال ـمـ ــحكمة الـ ـع ــام ـ ــة مبحافظــة عنيــزة برقــم (‪ )321120998‬وتــاري ـ ــخ‬\n‫‪1434/4/23‬ه ـ ؛ احملالــة إلينــا برقــم (‪ )34193038‬؛ املرفــق بهــا الصــك‬\n‫املســجل برقــم(‪ )34168512‬وتاريــخ ‪1434/3/22‬هــ؛ الصــادر مــن‬\n‫فضيلــة الشــيخ‪ ....... /‬القاضــي باحملكمــة ؛ اخلــاص بدعــوى‪....... /‬‬\n‫الوكيــل عــن أخيــه ‪ .......‬ضــد‪ ، ....... /‬بشــأن املطالبــة مببلــغ مالــي‬\n‫قــدره مائــة وخمســة آالف ريــال وقــد تضمــن الصــك حكــم فضيلتــه‬\n‫بإلــزام املدعــى عليــه بــأن يدفــع للمدعــي أصالــة املبلــغ املدعــى بــه وقــدره‬\n‫مائــة وخمســة اآلف ريــال ؛ علــى النحــو املفصــل فيــه‪ .‬وبدراســة الصــك‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة فإننــا نقــرر‬\n‫املصادقــة علــى احلكــم واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                         ‫وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                        ‫‪56‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":50,"source_page_end":56,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b97fc0f0caf32bc2862bb956adbc1e4fa47244ad53d2e935c195e5165920c321","normalized_text_hash":"1e5831ea48f9558a226cac6246a5927bae3f26099efd30a0938ea46964e9d43d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p50-34168512"},{"id":"ccb9425d-ba2d-55fa-a2cc-04111e4f0aaa","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -ضمان -كفالة غرامية -شهادة على الكفالة -اعتبار صرف الشيك بينة يف التسليم -احلكم بتسليم املبلغ.","document_number":"34309759","case_number":"33129123","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/1","year":"1434","subject":"قرض -ضمان -كفالة غرامية -شهادة على الكفالة -اعتبار صرف الشيك بينة يف التسليم -احلكم بتسليم املبلغ.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/9/1 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34309759 :‬‬\n                        ‫َر ْق ُم الدعوى‪33129123 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                ‫‪ 34354850‬تاريخه‪1434/11/9 :‬هـ‬\n\n\n\n     ‫قــرض ‪ -‬ضمــان ‪ -‬كفالــة غراميــة ‪ -‬شــهادة علــى الكفالــة ‪ -‬اعتبــار‬\n                ‫صــرف الشــيك بينــة يف التســليم‪ -‬احلكــم بتســليم املبلــغ‪.‬‬\n\n\n\n\n                       ‫‪ -1‬قوله تعالى ‪( :‬وملن جاء به حمل بعير وأنا به زعيم) ‪.‬‬\n                                ‫‪ -2‬قوله صلى اهلل عليه وسلم « الزعيم غارم» ‪.‬‬\n\n\n\n\n     ‫دعــوى املدعــي ضــد املدعــى عليــه وكالــة بــأن لــه يف ذمــة شــخص مبلغـ ًا‬\n     ‫مــن املــال قــدره مئتــان وخمســون ألــف ريــال قرضــه حســنة وقــد التــزم‬\n     ‫بســداد املبلــغ علــى دفعــات شــهرية وقــد وصــل مــن املبلــغ بعــض الدفعــات‬\n     ‫إال أنــه اختفــى ولــم يقــم بتســديد مــا بقــى يف ذمتــه وقــد ضمــن املدعــى‬\n     ‫عليــه اصالــة املديــن املقتــرض يف مبلــغ وقــدرة مئــة وتســعة آالف ريــال‬\n     ‫وطلــب املدعــى احلكــم علــى املدعــى عليــه اصالــة بتســليمه املبلــغ الــذي‬\n     ‫قــام بضمانــه بعــد خصــم املبالــغ املســددة وقدرهــا تســعون ألفــا وثمامنائــة‬\n     ‫وثمانيــة وثالثــون ريــا ًال ‪ ،‬أجــاب املدعــى عليــه وكالــة باإلنــكار ‪ ،‬يف‬\n     ‫جلســة أخــرى حضــر املدعــى عليــة اصالــة وصــادق علــى ضمانــه للمديــن‬\n     ‫املقتــرض وقــرر أن ضمانــه كان قبــل اســتالم املديــن للمبلــغ وأنــه متــى‬\n     ‫ثبــت تســليم الدائــن املبلــغ للمديــن فهــو ضامــن للمبلــغ ‪ -‬صــادق املدعــي‬\n‫‪57‬‬\n\f‫علــى مــا قــرره املدعــى عليــة اصالــة ‪ ،‬ثبــت لــدى ناظــر القضيــة اســتالم‬\n‫املديــن للمبلــغ مبوجــب شــيكات ‪ ،‬أجابــت اجلهــة املختصــة بأنــه مت‬\n‫صرفهــا مــن قبــل املديــن ‪ ،‬صــدر احلكــم علــى املدعــى عليــه بتســليم‬\n‫املدعــي املبلــغ املدعــى بــه ‪ ،‬قــرر املدعــى عليــه وكالــة عــدم القناعــة ‪،‬‬\n              ‫صــدر قــرار محكمــة االســتئناف باملوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة مبكــة‬\n‫ـاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬ ‫املكرمــة وبنـ ً‬\n‫العامــة مبكــة املكرمــة برقــم ‪ 33129123‬وتاريــخ ‪1433/02/20‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 33337776‬وتاريــخ ‪1433/02/20‬ه ـ ففــي‬\n‫يــوم اإلثنــن املوافــق ‪1433/09/18‬ه ـ افتتحــت اجللســة الســاعة ‪: 00‬‬\n‫‪ 11‬وفيهــا حضــر املدعــي‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ .....‬وحضــر حلضــوره املدعــى عليــه وكالــة ‪ .....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ .....‬بالوكالــة عــن ‪ .....‬مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة عــدل الثانيــة مبكــة املكرمــة برقــم ‪5852‬‬\n‫ا بــأن لــي يف ذمــة ‪.....‬‬‫وتاريــخ ‪1424/02/07‬ه ـ جلــد ‪ 807‬فادعــى قائ ـ ً‬\n‫مبلغ ـ ًا قــدره مئتــان وخمســون ألــف ريــال قرضــة حســنة إقترضهــا منــي‬\n‫علــى دفعــات وقــد التــزم يف تاريــخ ‪1432/07/25‬ه ـ بســداد املبلــغ علــى‬\n‫دفعــات شــهرية قــدر كل شــهر ثالثــة آالف وســبعة وعشــرين ريــا ًال وقــد‬\n‫وصلــت منهــا ســتة أقســاط بلــغ إجماليهــا ثمانيــة عشــر ألفـ ًا ومئــة واثنــن‬\n‫وســتني ريــا ًال اختفــى بعــد ذلــك وقــد ضمنــه مــوكل املدعــى عليــه هــذا‬\n\n\n                                                                                      ‫‪58‬‬\n\f     ‫احلاضــر مببلــغ مئــة وتســعة آالف ريــال مــن هــذه القرضــة الــذي وصــل‬\n     ‫منهــا هــذا املبلــغ أطلــب احلكــم عليــه شــرع ًا بتســليمي املبلــغ املتبقــي مــن‬\n     ‫قيمــة هــذه القرضــة التــي ضمنهــا وقــدره تســعون ألف ـ ًا وثمامنئــة وثمانيــة‬\n     ‫وثالثــون ريــا ًال هــذه دعــواي وبســؤال املدعــى عليــه وكالــة أجــاب‬\n     ‫ا مــا ذكــره املدعــي يف دعــواه مــن ناحيــة إقراضــه املبلــغ املدعــى‬      ‫قائ ـ ً‬\n     ‫بــه فهــذا ال أعلــم عنــه شــيئ ًا وكذلــك ضمــان موكلــي لــه مببلــغ مئــة‬\n     ‫البينــة‬\n         ‫وتســعة آالف ريــال ال صحــة لــه هــذه إجابتــي فطلبــت مــن املدعــي ّ‬\n     ‫فأبــرز ورقــة هــذا نصهــا بعــد املقدمــة أتعهــد وألتــزم أنــا املوقّ ــع إســمي‬\n     ‫أدنــاه ســعودي اجلنســية مبوجــب بطاقــة أحــوال رقــم الســجل املدنــي‬\n     ‫تنتهــي بتاريــخ ‪1440/11/05‬ه ـ علــى أن أكفــل املدعــو ‪ .....‬يف ســداد‬\n     ‫القــرض للدكتــور‪ ......‬علم ـ ًا أن قيمــة القــرض مئــة وتســعة آالف ريــال‬\n     ‫وأنــه يف حالــة عــدم ســداد القــرض املذكــور مــن قبــل املدعــو ‪ .....‬ســوف‬\n     ‫أقــوم أنــا شــخصي ًا ومــن حســابي اخلــاص بدفعــه للدكتــور ‪ .....‬دون‬\n     ‫شــرط أو قيــد وهــذا تعهــد منــي بذلــك الكفيــل الغــارم توقيعــه بتاريــخ‬\n     ‫‪1433/02/01‬ه ـ وبعرضهــا علــى املدعــى عليــه وكالــة أنكــر مــا جــاء‬\n     ‫البينــة علــى صحتهــا فأحضــر‪ .....‬ســعودي‬       ‫فيهــا فطلبــت مــن املدعــي ّ‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم الــذي شــهد بصحــة مــا جــاء يف‬\n     ‫هــذه الورقــة التــي نصهــا احلمــد هلل والصــاة والســام علــى أشــرف‬\n     ‫األنبيــاء أجمعــن فإنــه يف يــوم األحــد املوافــق ‪1432/07/03‬ه ـ قمــت أنــا‬\n     ‫املدعــو‪ /‬باســتدانة مبلــغ مــن املــال وقــدره ‪( 109000‬مئــة وتســعة آالف‬\n     ‫ريــال ســعودي) وذلــك مــن الدكتــور‪......... /‬قرضــة حســنة علــى أن ألتــزم‬\n     ‫ا علــى أقســاط شــهرية وملــدة ‪ 36‬شــهر ًا‬     ‫ا ورده رد ًا جميـ ً‬\n                                                                       ‫بســداده كامـ ً‬\n     ‫(ســت وثالثــن شــهر ًا هجري ـاً) دون تأخيــر أو مماطلــة حيــث تكــون‬\n\n\n‫‪59‬‬\n\f‫قيمــة القســط الشــهري مبلغـ ًا وقــدره ثالثــة آالف وســبعة وعشــرون ريــا ًال‬\n‫(‪ )3027‬اعتبــار ًا مــن تاريــخ ‪1432/07/25‬ه ـ ويف حــال عــدم التزامــي‬\n‫بالســداد فللدكتــور احلــق يف رفــع شــكوى ضــدي للجهــات املختصــة‬\n‫ومقاضاتــي أو كفيلــي حســب النظــام املقــر مبــا فيــه‪ /‬إبهامــه وتوقيعــه‬\n‫‪ ،‬شــاهد د‪ /‬توقيعــه ‪ ،‬شــاهد د‪ /‬توقيعــه أمــا مــا جــاء يف جانبهــا فقــد‬\n‫كتــب خــارج املكتــب ولــم أحضــره وقــد حضــر لدينــا يف املكتــب‬\n‫وزميلنــا املدعــي وشــخص ثالــث وقــد قــام الشــخص الثالــث بكفالــة يف‬\n‫هــذا املبلــغ وأنــا ال أعــرف املدعــى عليــه وال الشــخص وأطلــب إحضــار‬\n‫املدعــى عليــه عندكــم ألتأكــد منــه وتكــون شــهادتي علــى علــم‬\n‫ويقــن وحيــث األمــر مــا ذكــر طلبــت مــن املدعــى عليــه وكالــة إحضــار‬\n‫موكلــه وحضــر ســعودي اجلنســية بالســجل املدنــي رقــم وبتــاوة دعــوى‬\n‫املدعــي علــى املدعــى عليــه أصالــة أجــاب قائــا مــا ذكــره املدعــي يف‬\n‫دعــواه مــن ناحيــة ضمانــي مببلــغ مائــة وتســعة آالف ريــال فهــذا صحيــح‬\n‫إال أن ضمانــي كان قبــل تســليم هــذا املبلــغ ومتــى مــا أثبــت املدعــي‬\n‫تســليمه لهــذا املبلــغ املائــة والتســعة آالف ريــال فأنــا ضامــن لــه بهــذا‬\n‫املبلــغ هكــذا أجــاب وبعــرض ذلــك علــى املدعــي صــادق علــى ذلــك‬\n‫فطلبــت مــن املدعــي البينــة علــى تســليمه املبلــغ املدعــى بــه فابــرز صــورة‬\n‫الشــيك رقــم ‪ ...........‬وتاريــخ ‪1432/07/04‬ه ـ واملســحوب ألمــر والبالــغ‬\n‫قيمتــه ثمانــون ألــف ريــال مــن حســاب لــدى البنــك ‪ ......‬وصــورة الشــيك‬\n‫رقــم ‪ ...........‬وتاريــخ ‪1432/11/11‬ه ـ واملســحوب ألمــر‪ ....‬والبالــغ قيمته‬\n‫أربعــن ألــف ريــال مــن حســاب ‪ ....‬لــدى البنــك ‪ ......‬وصــورة الشــيك رقــم‬\n‫‪ .....‬وتاريــخ ‪1432/09/01‬ه ـ واملســحوب ألمــر ‪ .....‬والبالــغ قيمتــه ســبعة‬\n‫آالف ريــال مــن حســاب لــدى البنــك ‪ ......‬وصــورة الشــيك رقــم ‪...........‬‬\n\n\n                                                                                      ‫‪60‬‬\n\f     ‫وتاريــخ ‪1433/02/01‬ه ـ واملســحوب ألمــر والبالــغ قيمتــه مئــة ألــف ريــال‬\n     ‫مــن حســاب لــدى البنــك ‪ ......‬وبعرضهــا علــى املدعــى عليــه وكالــة قــال‬\n     ‫أطلــب الكتابــة للبنــك ‪ ......‬لإلفــادة عــن مســتلم قيمــة هــذه الشــيكات‬\n     ‫لذا قررت الكتابة ملؤسسة النقد العربي السعودي ملخاطبة البنك ‪......‬‬\n     ‫لإلفــادة عــن مســتلم هــذه الشــيكات وجــرى اإلطــاع على خطــاب مدير‬\n     ‫مؤسســة النقــد العربــي فــرع مكــة املكرمــة رقــم ‪ 340040004012‬يف‬\n     ‫‪1434/06/20‬ه ـ املتضمــن أنــه مت صــرف الشــيكات املرفقــة بخطــاب‬\n     ‫فضيلتكــم للمدعــو ‪ .......‬كمــا أرفــق البنــك صــور مــن الشــيكات بعــد‬\n     ‫ـاء علــى مــا تقدم مــن الدعوى‬    ‫صرفهــا (مرفقــه) وجــرى تأمــل القضيــة فبنـ ً‬\n     ‫واإلجابــة وإنــكار املدعــى عليــه وكالــة لدعــوى املدعــي واعتــراف‬\n     ‫املدعــى عليــه أصالــة بدعــوى املدعــي واســتعداده بتســليم املبلــغ املدعــى‬\n     ‫بــه للمدعــي بعــد ثبــوت هــذا املبلــغ بذمــة ‪ ......‬وبعــد اإلطــاع علــى خطــاب‬\n     ‫مديــر مؤسســة النقــد رقــم ‪ 34/19025‬يف ‪1434/06/19‬ه ـ املتضمــن‬\n     ‫اســتالم ‪ .....‬لقيمــة الشــيكات املشــار إليهــا واســتناد ًا لقولــه تعالــى (وملــن‬\n     ‫جــاء بــه حمــل بعيــر وأنــا بــه زعيــم ) الدالــة علــى ضمــان حمــل البعيــر مــع‬\n     ‫أنــه لــم يجــب وقولــه صلــى اهلل عليــه وســلم «الزعيــم غــارم» ولــكل مــا‬\n     ‫ســبق أفهمــت املدعــى عليــه وكالــة أنــه يلــزم موكلــه تســليم املدعــي‬\n     ‫املبلــغ املدعــى بــه وقــدره تســعون ألف ـ ًا وثمامنائــة وثمانيــة وثالثــون ريــا ًال‬\n     ‫وبذلــك حكمــت وبعــرض احلكــم علــى املدعــى عليــه وكالــة قــرر عــدم‬\n     ‫القناعــة وأفهــم بتعليمــات اإلســتئناف وبذلــك انتهــت هــذه الدعــوى وباهلل‬\n     ‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                                   ‫يف ‪1434/08/21‬هــ‪.‬‬\n\n\n\n‫‪61‬‬\n\f‫احلمــد هلل وحــده وبعــد جــرى اإلطــاع علــى املعاملــة الــواردة إلينــا مــن‬\n‫رئيــس محكمــة اإلســتئناف مبنطقــة مكــة املكرمــة املكلــف برقــم‬\n‫‪ 341496452‬يف ‪1434/11/13‬ه ـ املرفــق بهــا قــرار تصديــق الدائــرة‬\n‫احلقوقيــة السادســة رقــم ‪ 34354850‬يف ‪1434/11/09‬ه ـ املتضمــن‬\n‫دعــوى ‪ .....‬ضــد ‪ .....‬احملكــوم فيــه مبــا دون باطنــه ‪ ،‬وبدراســة احلكــم‬\n‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم‬\n‫‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                          ‫وســلم ‪ .‬حــرر يف ‪1434/11/24‬ه ـ‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد‪ :‬فق ــد ج ــرى‬\n‫م ّنــا نح ــن رئيــس وأعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n‫االستئناف مبنطقة مك ــة املكرم ــة االطال ُع عل ــى هذا احلكم الصادر‬\n‫مــن فضيلــة الشــيخ ‪ ......‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‬\n‫واملســجل بع ــدد ‪ 34309759‬وتاريــخ ‪1434/9/1‬ه ـ املتضمــن دعــوى‬\n‫‪ .........‬ضــد ‪ ........‬احملكــوم في ــه مبــا دون باطنــه ‪ ،‬وبدراس ــة احلكــم‬\n‫وص ــورة ضبط ــه و الئحته االعتراضية تق ــررت املوافق ــة عل ــى احلكم ‪،‬‬\n‫واهلل املوفــق وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪62‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":57,"source_page_end":62,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ef1b785bf10bd67d72700d245f2886516e663b10b9d52017316594ab561945f0","normalized_text_hash":"be771023c82213876163760bbc9f366b61120a5de64c23430e04d4578aad5ed4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p57-34309759"}]$archive_payload$::jsonb) AS x LIMIT 25
